{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Duvelisib, the closest analogue by Morgan similarity, has a measured absolute oral bioavailability of 42% in humans, directly supporting F >= 20% for this kinase-inhibitor-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Vorasidenib, which shares the chiral trifluoromethyl-bearing aminopyrimidine motif, has a mean absolute oral bioavailability of 34% in humans over a 10-200 mg dose range, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Erlotinib, a heteroaromatic kinase inhibitor with an aminopyrimidine/quinazoline-like core, has an absolute oral bioavailability of about 76% in cancer patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lapatinib, despite qualitative 'low bioavailability' descriptions, was estimated at 30% oral bioavailability in patients, which is above the 20% threshold and supports a high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "PK11195, a lipophilic heteroaromatic drug, has a stable absolute bioavailability of 33% in healthy volunteers, providing additional transferable evidence for F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a kinase-inhibitor-like heteroaromatic drug candidate. All transferable experimental analogues with human oral bioavailability measurements fall at or above 30% (duvelisib 42%, vorasidenib 34%, erlotinib ~60-76%, lapatinib 30%, PK11195 33%), and no affirmative evidence indicates F < 20%. Therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "Morgan similarities to the evidence molecules are low (0.16-0.26), limiting structural transferability.",
    "No query-specific data on solubility, permeability, first-pass metabolism, or transporter-mediated efflux are available.",
    "Some analogue records are qualitative or not explicitly absolute bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

